  rs3_weymouth:['韦茅斯','Weymouth',50.614,-2.457,'英格兰西南多塞特郡海港；流亡法国九年的玛格丽特王后与十七岁王子爱德华于1471年4月14日巴尼特之战当天在此登陆。'],
