    hp(d,'w_paris',{kind:'battle',note:'885—886年维京人围城；胖子查理带大军赶到，付七百磅银子了事。'});hp(d,'de_trebur');
    hr(d,[[51.95,4.15],[51.75,5.3],[51.21,6.02],[50.78,6.08]],HC.war);hr(d,[[51.85,6.2],[51.3,6.75],[50.94,6.96],[50.36,7.6],[49.75,6.64]],HC.war);
