    hp(d,'gr_besancon',{left:1,note:'亨利在此过圣诞，母亲家的亲戚勃艮第伯爵威廉款待他。'});
    hp(d,'fr_mtcenis',{left:1,note:'1077年1月隆冬翻山；据兰佩特所记，王后被放在牛皮上拖下山。'});
    hp(d,'it_canossa',{note:'1077年1月25日起亨利在城门外站了三天，28日得赦免。'});
