    hp(d,'w_bordeaux',{note:'1137年7月25日，路易七世在此迎娶十五岁的阿基坦女公爵埃莉诺。'});
    hp(d,'c2_beaugency',{left:1,note:'1152年3月21日，主教会议在此以近亲为由宣布路易七世与埃莉诺的婚姻无效。'});
    hp(d,'k_poitiers',{note:'1152年5月18日，埃莉诺在此改嫁十九岁的安茹伯爵亨利，阿基坦随之归亨利。'});
