    hp(d,'rome',{kind:'battle',note:'962年奥托一世在此加冕为帝，此后三百年皇帝与罗马教宗死磕，五位皇帝遭七次绝罚。'});
    hp(d,'k_frankfurt',{left:1,note:'1220年腓特烈二世在此颁《与教会诸侯协定》，把铸币、税关与筑城权让给地方主教。'});
    hp(d,'k_worms',{left:1,note:'1122年《沃尔姆斯宗教协定》与1231年《恩惠诸侯法令》，世俗诸侯正式获称“邦君”。'});
