    hp(d,'ge1_bingen',{kind:'battle',note:'1300年10月美因茨、科隆、特里尔三大主教在此结盟欲废阿尔布雷希特，1301年被阿尔布雷希特攻克。'});
    hp(d,'colonia',{left:1,note:'1302年阿尔布雷希特联合莱茵市民顺江北上，逼科隆与特里尔大主教割让关税投降。'});
    hp(d,'c3_vienna',{note:'阿尔布雷希特一世背靠富庶的奥地利私产，兵力远胜前任拿骚的阿道夫。'});
