    hp(d,'no_messina',{note:'西西里东岸大港，城中与周边仍住着不少说希腊语的东正教徒。'});
    hp(d,'vp_lucera',{note:'1220年代起腓特烈二世将两三万西西里穆斯林迁居于此，1300年被安茹的查理二世铲平。'});
