    hr(d,[[45.04,3.89],[43.6,1.44],[43.3,-0.37],[43.01,-1.32],[42.82,-1.64],[42.36,-2.47],[42.34,-3.7],[42.6,-5.57],[42.46,-6.06],[42.88,-8.545]],HC.route);
