    hp(d,'w_zaragoza',{left:1,note:'胡德家的泰法；1065年其王夺回巴尔瓦斯特罗，1073年又与纳瓦拉王订约，共防翻山而来的远征军。'});
    hp(d,'sc_jaca',{note:'阿拉贡王桑乔·拉米雷斯的都城；他1068年到罗马自认教宗的封臣。'});
