    hp(d,'ic_tusculum',{note:'1149年尤金三世在此落脚，罗杰二世派来骑士，教宗用他们打罗马人。'});
    hp(d,'cd_farfa',{left:1,note:'1145年2月15日尤金三世当选后出城，三天后在这里受祝圣。'});
    hp(d,'cd_viterbo');
