    hp(d,'w_benevento',{note:'1156年6月18日，哈德良四世在此承认西西里的威廉一世的王国，首相罗兰经手。'});
    hp(d,'rome',{note:'1159年9月7日在圣彼得大教堂一选两个；1179年3月第三次拉特兰会议定下三分之二。'});
    hp(d,'i_ninfa',{left:1,note:'1159年9月20日，亚历山大三世在此受祝圣。'});
    hp(d,'cd_farfa',{left:1,note:'1159年10月4日，维克托四世在此受祝圣。'});
    hp(d,'w_pavia',{note:'1160年2月，腓特烈一世召集的会议在此认维克托四世。'});
    hp(d,'w_venice',{note:'1177年腓特烈一世在此认了亚历山大三世。'});
