    hp(d,'av_palestrina',{left:1,note:'科隆纳家的老巢；1347年11月科隆纳等贵族在罗马城外跟科拉的民兵交战。'});
    hp(d,'cd_viterbo',{left:1,note:'阿尔沃诺斯1353年起从这一带的地方豪强手里逐城收回教宗国。'});
