    hp(d,'rome',{kind:'battle',note:'1367年10月16日乌尔班五世进罗马，六十年来头一位；1369年东罗马皇帝约翰五世在此皈依。'});
    hp(d,'cd_viterbo',{left:1,note:'1367年乌尔班五世进罗马前在此驻留；教宗国各城仍不太平。'});
