    hp(d,'sc_basel',{left:1,note:'会议多数要在巴塞尔、阿维尼翁或萨伏依跟希腊人开会；希腊人要去意大利。'});
    hp(d,'c3_ferrara',{left:1,note:'1437年9月尤金四世下令把会议移到此地，1438年1月开幕，4月东罗马使团七百多人抵达。'});
    hp(d,'ci_florence',{kind:'battle',note:'1439年7月6日尤金四世与约翰八世在此签《愿诸天欢腾》，宣布东西教会合并。'});
