    hp(d,'changan',{kind:'battle',note:'446年太武帝在此一座寺里搜出兵器，随即下诏毁佛、坑杀沙门。'});
    hp(d,'jiankang',{note:'东晋都城；“王与马，共天下”，皇权弱，门阀强。'});
    hp(d,'lushan');
