    hp(d,'antioch',{note:'1100年博希蒙德赶走希腊牧首，换上拉丁宗主教；1105年博希蒙德把公国交给侄子坦克雷德。'});
    hp(d,'haran',{kind:'battle',note:'1104年5月十字军在此败给突厥人，埃德萨伯爵鲍德温被俘。'});
    hp(d,'fr_chartres',{left:1,note:'1106年博希蒙德在此娶法王腓力一世的女儿康斯坦丝，在教堂台阶上招兵打皇帝。'});
    hp(d,'dyrrachium',{kind:'battle',note:'1107年10月起博希蒙德围城，久攻不下。'});
    hp(d,'cs_devol');
    hr(d,[[36.12,35.93],[35.4,30.5],[36.4,22.6],[39.62,19.92],[41.125,16.867],[41.893,12.483],[44.0,10.0],[45.7,4.8],[48.447,1.489]],HC.crusade);
