    hp(d,'c3_genoa',{note:'腓力雇热那亚船队，载六百五十名骑士东渡。'});
    hp(d,'no_messina',{note:'1190年9月两王到此过冬；10月4日理查攻进城；1191年3月两王立约退婚。'});
    hp(d,'c3_limassol',{note:'1191年5月理查在此登陆，12日与贝伦加丽亚成婚。'});
