    hp(d,'cm_krak',{note:'13世纪修成内外两重城墙；1291年哈马的兵在此接手大投石机“曼苏里”，运往阿卡。'});
    hr(d,[[36.3,28.0],[35.6,30.4],[34.5,32.9],[33.6,34.4],[32.93,35.05]],HC.italy);
