    hp(d,'uk3_chester',{left:1,note:'907年埃塞尔弗莱德重修切斯特城防，挡住爱尔兰海方向的维京人。'});
    hp(d,'k_york',{note:'927年埃塞尔斯坦攻下维京人的约克王国，统一亨伯河两岸。'});
    hp(d,'uk3_eamont',{note:'927年7月12日埃塞尔斯坦在此接受苏格兰王君士坦丁二世、斯特拉斯克莱德王等臣服。'});
    hp(d,'uk3_brunanburh',{kind:'battle',left:1,note:'937年埃塞尔斯坦与弟弟埃德蒙在此大破苏格兰、斯特拉斯克莱德与都柏林维京联军。'});
