    hp(d,'uk4_nidaros',{note:'1028年克努特率五十艘战船北上至此，兼任挪威国王。'});
    hr(d,[[55.64,12.08],[53.6,0.1],[51.59,0.68],[51.51,-0.09]],HC.war);
