    hp(d,'uk4_westminster',{left:1,note:'1066年12月25日圣诞节，威廉在此加冕为英格兰国王威廉一世。'});
    hr(d,[[51.50,-0.13],[53.96,-1.08],[53.99,-0.91]],HC.britain);
