    hp(d,'uk4_westminster',{left:1,note:'王廷中心；全境四千多名本土旧地主被剥夺产业，土地转封约一百八十名诺曼大男爵。'});
    hr(d,[[51.50,-0.13],[53.96,-1.08],[54.78,-1.58],[53.96,-1.08],[53.19,-2.89]],HC.war);
