    hp(d,'uk4_winchester',{left:1,note:'1086年调查汇总为两大卷《末日审判书》，存入温彻斯特王室金库。'});
    hp(d,'pl_mantes',{kind:'battle',note:'1087年7月威廉一世攻焚此城时战马踏热灰受惊，肚腹撞破在马鞍前桥上。'});
    hp(d,'fr_rouen',{note:'1087年9月9日威廉一世在城西圣热尔韦修道院病逝，临终分诺曼底与英格兰予长子、次子。'});
