    hp(d,'uk6_clontarf',{kind:'battle',note:'1014年4月23日，布莱恩·博鲁大军在此击溃维京与伦斯特联军，布莱恩在帐中被逃兵劈死。'});
    hr(d,[[52.52,-7.89],[53.36,-6.21]],HC.celt);
