    hp(d,'uk6_ferns',{note:'1171年5月迪尔梅德在此病死，女婿强弓手以妻权接掌伦斯特。'});
    hr(d,[[51.68,-4.92],[52.34,-6.46]],HC.war);hr(d,[[51.68,-4.92],[52.26,-7.11],[53.34,-6.27]],HC.war);
