    hp(d,'rome',{note:'1215年8月24日，英诺森三世发通谕宣布《大宪章》非法无效，绝罚叛乱男爵。'});
    hp(d,'k_london',{note:'1216年6月法王王储路易应叛乱男爵之邀进占伦敦；1217年9月签和约撤走。'});
    hp(d,'uk8_newark',{left:1,note:'1216年10月约翰穿过沃什湾流沙丢掉宝车后，于10月18日夜在此染痢疾暴卒。'});
    hp(d,'uk8_gloucester',{left:1,note:'1216年10月28日，威廉·马歇尔在此扶九岁的亨利三世加冕，11月重发删改版《大宪章》。'});
